INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Programmablaufplan nur für Programmierer nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Analysten und Planer"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Programmablaufplan?', 3, '[{"text": "Ablaufvisualisierung", "correct": true, "because": "Zeigt Prozessschritte"}, {"text": "Datenmodellierung", "correct": false, "because": "ERM-Thema"}, {"text": "Hardwarezuordnung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Programmablaufplan?', 5, '[{"text": "Entscheidungen", "correct": true, "because": "Steuern Ablauf"}, {"text": "Schleifen", "correct": true, "because": "Wiederholungen darstellen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Komponenten", "correct": false, "because": "Komponentendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Programmablaufpläne zeigen Abläufe. b) Sie ersetzen Zustandsdiagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zustände sind anderes Diagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Programmablaufplan?', 4, '[{"text": "Entscheidungspunkte", "correct": false, "because": "Kern des Ablaufs"}, {"text": "Prozessschritte", "correct": false, "because": "Grundlage der Visualisierung"}, {"text": "UI-Design", "correct": true, "because": "Kein Ablauffaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programmablaufplan auch Datenflüsse zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Ablauf, nicht Daten"}, {"text": "Ja", "correct": false, "because": "Datenflussdiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Entscheidung?', 3, '[{"text": "Raute", "correct": true, "because": "Standard für Verzweigungen"}, {"text": "Rechteck", "correct": false, "because": "Nur Prozessschritt"}, {"text": "Pfeil", "correct": false, "because": "Nur Übergang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern einen Programmablaufplan?', 5, '[{"text": "Start-/Endpunkte", "correct": true, "because": "Definieren Grenzen"}, {"text": "Schleifen", "correct": true, "because": "Wiederholungen sichtbar"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Programmablaufpläne sind für Abläufe. b) Sie zeigen Hardwarezuordnung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Programmablaufplan?', 4, '[{"text": "Entscheidungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Prozessschritte", "correct": false, "because": "Grundlage des Plans"}, {"text": "Netzwerkknoten", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Programmablaufplan nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsprozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symbole nutze ich im Programmablaufplan?', 4, '[{"text": "Raute", "correct": true, "because": "Entscheidungen darstellen"}, {"text": "Rechteck", "correct": true, "because": "Prozessschritte zeigen"}, {"text": "Abhängigkeitspfeil", "correct": false, "because": "Paketdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Programmablaufpläne überflüssig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hilfreich für Ablaufübersicht"}, {"text": "Ja", "correct": false, "because": "Nützliches Werkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Programmablaufplan?', 3, '[{"text": "Klarheit der Schritte", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Technische Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Programmablaufpläne zeigen Entscheidungen. b) Sie sind für Modulstruktur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Modulstruktur ist Komponentendiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Programmablaufplan?', 5, '[{"text": "Ablaufübersicht", "correct": true, "because": "Klarheit über Prozesse"}, {"text": "Entscheidungsvisualisierung", "correct": true, "because": "Verzweigungen sichtbar"}, {"text": "Hardwareplanung", "correct": false, "because": "Verteilungsdiagramm"}, {"text": "Datenmodellierung", "correct": false, "because": "ERM-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Programmablaufplan unwichtig?', 3, '[{"text": "Schleifen", "correct": false, "because": "Wiederholungen darstellen"}, {"text": "Entscheidungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Ablauffaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Programmablaufplan auch Zustände?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Ablauf, nicht Zustände"}, {"text": "Ja", "correct": false, "because": "Zustandsdiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Programmablaufpläne für Tests nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Definieren Testabläufe"}, {"text": "Nein", "correct": false, "because": "Testfälle ableitbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für einen Prozessschritt?', 4, '[{"text": "Rechteck", "correct": true, "because": "Standard für Schritte"}, {"text": "Kreis", "correct": false, "because": "Start-/Endpunkt"}, {"text": "Pfeil", "correct": false, "because": "Nur Übergang"}]');
